const t=(en,zh)=>lang==='zh'?zh:en;
function dateText(value,opts={}){return new Intl.DateTimeFormat(lang==='zh'?'zh-CN':'en-US',{timeZone:$('timezone').value,...opts}).format(new Date(value));}
function setCopy(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.lang=lang;$('language').textContent=lang==='zh'?'EN':'中文';$('language').setAttribute('aria-label',lang==='zh'?'Switch to English':'切换中文');document.querySelectorAll('[data-copy]').forEach(el=>{const c=copy[el.dataset.copy];if(c)el.innerHTML=c[lang==='zh'?1:0];});$('signal-query').placeholder=t('Reset, account, author','重置、账号、作者');$('post-url').placeholder='https://x.com/account/status/123456789…';$('refresh').setAttribute('aria-label',t('Refresh sources','刷新数据源'));$('refresh').title=t('Refresh sources','刷新数据源');$('reset-button').setAttribute('aria-label',t('Press the pretend reset button','按下不会改变额度的许愿按钮'));$('press-count').textContent=clicks;render();renderLookup();}
const kindLabel={promise:['Explicit promise','明确承诺'],confirmed:['Reset reported','报告已重置'],negative:['Delay / denial','推迟 / 否认'],banked:['Banked reset','重置卡'],repair:['Relevant repair','相关修复'],hint:['Reset hint','重置暗示'],release:['Product release','产品发布'],policy:['Reset policy','重置规则'],context:['Context only · no weight','背景动态 · 不计权重'],incident:['Related incident','相关故障']};
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function renderLookup(){
  const status=$('lookup-status'),result=$('lookup-result');
  const messages={idle:t('The original post is checked without an X account. Community posts stay separate from official evidence.','无需 X 账号即可检查原帖；社区帖子与官方依据会分开标记。'),loading:t('Checking the original post…','正在读取原帖…'),invalid_url:t('Enter a valid x.com or twitter.com post link.','请输入有效的 x.com 或 twitter.com 帖子链接。'),not_related:t('This post does not appear to concern a Codex or ChatGPT Work reset.','这条帖子似乎与 Codex 或 ChatGPT Work 重置无关。'),post_not_found:t('That public post could not be found.','未能找到这条公开帖子。'),source_unavailable:t('The public X source is unavailable. Try again later.','公开 X 数据源暂不可用，请稍后重试。'),found:t('Post added to this page for review.','帖子已加入当前页面，供你核对。')};
  status.textContent=messages[lookupState.kind]||messages.source_unavailable;status.className=['invalid_url','not_related','post_not_found','source_unavailable'].includes(lookupState.kind)?'error':'';
  result.replaceChildren();result.hidden=lookupState.kind!=='found';
  if(lookupState.kind==='found'){
    const post=lookupState.post;
    result.append(node('strong','',`${post.author} (@${post.handle})`),node('small','',post.authority==='first-party'?t('First-party source','官方来源'):t('Community post · context only','社区帖子 · 仅供参考')),node('p','',post.excerpt));
    const link=node('a','',t('Open original ↗','打开原帖 ↗'));link.href=post.url;link.target='_blank';link.rel='noopener noreferrer';result.append(link);
  }
}
function renderSignals(model){
  const query=$('signal-query').value.trim().toLocaleLowerCase();
  const resetKinds=new Set(['promise','confirmed','negative','banked','hint','policy']);
  const signals=model.factors.filter(s=>(selectedFilter==='all'||selectedFilter==='resets'&&(resetKinds.has(s.kind)||s.related)||selectedFilter==='relevant'&&(s.kind!=='context'||s.related))&&(!query||[s.author,s.handle,s.excerpt,s.kind].some(part=>String(part||'').toLocaleLowerCase().includes(query))));
  const list=$('signal-list');list.replaceChildren();
  if(!signals.length){list.append(node('p','empty',query?t('No fetched posts match this search. Try the wider X search.','已抓取的帖子中没有匹配项，可试试右侧的 X 全站搜索。'):t('No matching clues in the tracked feeds.','已追踪动态中暂无匹配线索。')));return;}
  const sorted=sortSignals(signals,selectedFilter==='all'?'all':'relevant',Date.now());
  for(const s of sorted.slice(0,expanded?sorted.length:5)){
    const article=node('article',`signal ${s.kind}${newIds.has(s.id)?' fresh':''}`);
    const symbol={promise:'↗',confirmed:'✓',negative:'−',banked:'▣',repair:'+',hint:'?',release:'↑',policy:'i',context:'·',incident:'!'}[s.kind]||'·';
    article.append(node('span','signal-icon',symbol));
    const content=node('div','signal-content'),head=node('div','signal-head'),identity=node('div','signal-identity');
    identity.append(node('span','signal-author',s.author));
    if(s.handle&&!s.id.startsWith('status-'))identity.append(node('span','signal-handle',`@${s.handle}`));
    head.append(identity);
    const time=node('time','',dateText(s.createdAt,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}));time.dateTime=s.createdAt;head.append(time);
    content.append(head,node('p','signal-text',s.excerpt));
    const bottom=node('div','signal-bottom');
    const label=s.archived?t('Reviewed report','已核验记录'):s.authority==='community'?t('Community post','社区帖子'):s.kind==='promise'&&s.stage==='committed'?t('Official reset commitment','官方重置承诺'):s.kind==='banked'&&s.stage==='announced'?t('Banked reset · rolling out','重置卡 · 发放中'):s.kind==='banked'&&s.stage==='planned'?t('Banked reset · planned','重置卡 · 计划中'):kindLabel[s.kind]?.[lang==='zh'?1:0]||s.kind;
    const badge=node('span','signal-tag',label);
    if(s.currentWeight)badge.append(node('span','signal-weight',(s.currentWeight>0?'+':'')+s.currentWeight.toFixed(2)));
    bottom.append(badge);
    const link=node('a','',t('Original ↗','查看原文 ↗'));link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';bottom.append(link);
    content.append(bottom);article.append(content);list.append(article);
  }
  if(sorted.length>5){const more=node('button','show-more',expanded?t('Show less','收起'):t(`Show ${sorted.length-5} more posts`,`展开另外 ${sorted.length-5} 条动态`));more.type='button';more.addEventListener('click',()=>{expanded=!expanded;render();});list.append(more);}
}
function render(updateSignals=true){if(!snapshot)return;const model=forecast({...snapshot,signals:[...snapshot.signals,...lookupPosts.values()]},Date.now(),$('timezone').value);const age=Math.max(0,Math.floor((Date.now()-Date.parse(snapshot.checkedAt))/1000));const stale=age>45;const discovery=snapshot.sources.discovery||{state:'unavailable',lastSuccess:null};const xOK=snapshot.sources.x.state==='available'&&!stale&&!failed;const discoveryOK=['available','partial'].includes(discovery.state)&&!stale&&!failed;const statusOK=snapshot.sources.status.state==='available'&&!stale&&!failed;const knownX=!!snapshot.sources.x.lastSuccess&&Date.now()-Date.parse(snapshot.sources.x.lastSuccess)<24*3600000;const knownDiscovery=!!discovery.lastSuccess&&Date.now()-Date.parse(discovery.lastSuccess)<24*3600000;const canEstimate=knownX||knownDiscovery||lookupPosts.size>0;const canShowToday=canEstimate||!!model.today.observed;const value=model.today.probability;
  $('today-value').textContent=canShowToday?value:'--';$('tomorrow-value').textContent=canEstimate?model.tomorrow.probability:'--';$('today-date').textContent=dateText(Date.now(),{month:'short',day:'numeric'});$('tomorrow-date').textContent=dateText(model.tomorrow.start,{month:'short',day:'numeric'});
  $('verdict').textContent=!canShowToday?t('The radar is quiet.','雷达暂时离线。'):model.today.observed?.kind==='banked'?t('A reset card is rolling out.','重置卡正在发放。'):model.today.observed?t('The reset was reported complete.','已公开报告重置完成。'):model.today.commitment?t('An official reset is promised.','官方已明确承诺重置。'):value>=65?t('The button is looking tempting.','按钮看起来快按下了。'):value>=35?t('Something might be cooking.','好像有点动静了。'):t('Keep a little hope in reserve.','留一点希望，先忙别的。');
  $('today-note').textContent=model.today.observed?.kind==='banked'?t('A first-party banked reset grant was announced. Eligible accounts receive a card to use later; limits do not refill automatically.','官方宣布发放重置卡。符合条件的账号可稍后自行使用，额度不会自动刷新。'):model.today.observed?t(`${model.today.observed.author} reports the reset has completed. This confirms a public statement, not delivery to your account.`,`${model.today.observed.author} 报告重置已完成。这里确认的是公开声明，并非对你账号的检测。`):model.today.commitment?t(`${model.today.commitment.author} explicitly promised a reset. Completion has not yet been confirmed in the tracked posts.`,`${model.today.commitment.author} 明确承诺重置；已追踪帖子中尚未确认执行完成。`):copy.todayNote[lang==='zh'?1:0];
  const decision=model.today.observed||model.today.commitment;$('decision-source').hidden=!decision;$('decision-source').href=decision?.url||'#signal-list';$('decision-source').textContent=t('Original post ↗','查看原帖 ↗');
  const latestLine=$('latest-event');latestLine.hidden=!model.latestObserved;latestLine.replaceChildren();
  if(model.latestObserved){const last=model.latestObserved;const time=node('time','',dateText(last.createdAt,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}));time.dateTime=last.createdAt;const link=node('a','',t('Original ↗','原帖 ↗'));link.href=last.url;link.target='_blank';link.rel='noopener noreferrer';latestLine.append(node('strong','',t('Latest official reset report','最近一次官方重置报告')),time,link);if(!model.today.observed)latestLine.append(node('span','latest-note',t("Today's percentage is for another event.",'今天的百分比指再次发生重置。')));}
  $('dot-meter').replaceChildren(...Array.from({length:100},(_,i)=>node('i',canShowToday&&i<value?'on':'')));
  $('connection').replaceChildren(node('span','status-dot '+(xOK&&discoveryOK&&statusOK?'connected':'partial')),node('span','',xOK&&discoveryOK&&statusOK?t('LIVE · auto-sync ~10s','实时 · 约 10 秒同步'):t('Partial coverage · read source status','数据覆盖不完整 · 请查看来源状态')));
  $('checked-at').textContent=t(`CHECKED ${age}s AGO · `,`${age} 秒前检查 · `)+dateText(snapshot.checkedAt,{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZoneName:'short'});
  for(const [id,ok,source] of [['x-state',xOK,snapshot.sources.x],['discovery-state',discoveryOK,discovery],['status-state',statusOK,snapshot.sources.status]]){$(id).textContent=source.state==='partial'?t('PARTIAL','部分可用'):ok?t('CONNECTED','已连接'):source.lastSuccess?t('STALE','旧数据'):t('UNAVAILABLE','不可用');$(id).className=ok?'':'bad';}
  const warning=$('source-warning');warning.hidden=xOK&&discoveryOK&&statusOK;warning.textContent=failed?t('The last refresh failed. Any numbers shown use the previous snapshot, not a live reading.','本次刷新失败。当前数字如仍显示，使用的是上一份快照，并非实时数据。'):!xOK&&model.today.observed?.archived?t('The live Tibo feed is unavailable. The completed reset report comes from our reviewed, source-linked archive.','Tibo 实时动态暂不可用；已完成的重置报告来自本站核对过、附有原帖链接的档案。'):!xOK?t('The Tibo feed is delayed or unavailable. Missing posts can materially change these odds.','Tibo 动态延迟或不可用。未读到的新帖可能显著改变概率。'):!discoveryOK?t('Other official X feeds are delayed or unavailable. The tracked post list is incomplete.','其他官方 X 动态延迟或不可用，站内帖子列表不完整。'):t('OpenAI Status is temporarily unavailable. The estimate currently relies on X signals.','OpenAI 状态源暂不可用，估计目前依赖 X 线索。');if(updateSignals)renderSignals(model);
}
async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;$('refresh').classList.add('busy');try{const response=await fetch('/api/reset-radar',{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!response.ok)throw new Error();const data=await response.json();if(!Array.isArray(data.signals)||!data.sources?.x||!data.sources?.status)throw new Error();const merged=mergeSnapshot(snapshot,data);newIds=new Set(snapshot?merged.signals.filter(s=>!snapshot.signals.some(old=>old.id===s.id)).map(s=>s.id):[]);snapshot=merged;failed=false;try{localStorage.setItem('wtr.snapshot',JSON.stringify(snapshot));}catch{}render();}catch{failed=true;if(snapshot){render();}else{$('connection').replaceChildren(node('span','status-dot partial'),node('span','',t('Sources temporarily unavailable','数据源暂时不可用')));$('signal-list').replaceChildren(node('p','empty',t('Could not load sources. Please try refresh in a moment.','暂时无法读取来源，稍后点击刷新重试。')));$('source-warning').hidden=false;$('source-warning').textContent=t('No live evidence, no invented odds. We will try again automatically.','没有实时依据，就不编造概率。页面会自动重试。');}}finally{loading=false;$('refresh').disabled=false;$('refresh').classList.remove('busy');}}
function updateSearchLink(){const query=$('signal-query').value.trim().slice(0,100);const url=new URL('https://x.com/search');url.searchParams.set('q',`(Codex OR "ChatGPT Work") (reset OR "banked reset")${query?' '+query:''}`);url.searchParams.set('f','live');$('x-search').href=url.toString();}
async function submitLookup(event){
  event.preventDefault();if(lookupBusy)return;
  lookupBusy=true;lookupState={kind:'loading'};$('lookup-button').disabled=true;renderLookup();
  try{
    const response=await fetch(`/api/reset-post?url=${encodeURIComponent($('post-url').value.trim())}`,{cache:'no-store',signal:AbortSignal.timeout(16000)});
    const data=await response.json();
    if(!response.ok){lookupState={kind:data.error||'source_unavailable'};return;}
    const post=data.post;
    if(!post?.id||!post?.url||!post?.createdAt)throw new Error('Invalid source response');
    lookupPosts.set(post.id,post);newIds.add(post.id);lookupState={kind:'found',post};render();
  }catch{lookupState={kind:'source_unavailable'};}
  finally{lookupBusy=false;$('lookup-button').disabled=false;renderLookup();}
}
$('language').addEventListener('click',()=>{lang=lang==='en'?'zh':'en';try{localStorage.setItem('chefzc.language',lang);}catch{}setCopy();});$('timezone').addEventListener('change',render);$('refresh').addEventListener('click',refresh);
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{selectedFilter=button.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));render();}));
$('signal-query').addEventListener('input',()=>{expanded=false;updateSearchLink();render();});
$('post-lookup').addEventListener('submit',submitLookup);
const wishes=[['Hope sent. Tibo remains unbothered.','希望已发送，Tibo 可能还在喝咖啡。'],['Quota +0. Morale +100.','额度 +0，士气 +100。'],['You pressed it. The universe took a note.','你按下了，宇宙说它记住了。'],['Still 0 tokens. Immaculate button technique.','额度还是 0，但你按得很专业。'],['Please do not feed the refresh button.','请不要把最后的额度喂给刷新键。']];
$('reset-button').addEventListener('click',()=>{clicks++;$('press-count').textContent=clicks;try{localStorage.setItem('wtr.hopes',String(clicks));}catch{}$('press-message').textContent=wishes[(clicks-1)%wishes.length][lang==='zh'?1:0];const btn=$('reset-button');btn.classList.add('pressed');setTimeout(()=>btn.classList.remove('pressed'),160);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const r=btn.getBoundingClientRect();for(let i=0;i<14;i++){const p=node('i','particle');p.style.left=(r.left+r.width/2)+'px';p.style.top=(r.top+r.height/2)+'px';p.style.background=['#a6d933','#b099e2','#242621'][i%3];const angle=i/14*Math.PI*2;p.style.setProperty('--x',Math.cos(angle)*(65+Math.random()*85)+'px');p.style.setProperty('--y',Math.sin(angle)*(65+Math.random()*85)+'px');$('particles').append(p);setTimeout(()=>p.remove(),850);}}});
try{const saved=JSON.parse(localStorage.getItem('wtr.snapshot'));if(saved?.sources?.x&&Date.now()-Date.parse(saved.checkedAt)<24*3600000)snapshot=saved;}catch{}
setCopy();updateSearchLink();refresh();setInterval(()=>{if(!document.hidden)refresh();},10000);setInterval(()=>{if(!document.hidden)render(false);},5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){render(false);if(!snapshot||Date.now()-Date.parse(snapshot.checkedAt)>10000)refresh();}});window.addEventListener('online',()=>{if(!document.hidden)refresh();});
